readonly struct CacheKey(string tenant, string attemptId)
{
    public string Tenant { get; } = tenant;
    public string AttemptId { get; } = attemptId;
}

static bool TryParseAttempt(string raw, out int attemptNo)
    => int.TryParse(raw, out attemptNo);

static bool Exists(in CacheKey key, IReadOnlyDictionary<CacheKey, byte> map)
    => map.ContainsKey(key);

static void Swap(ref int a, ref int b)
{
    int temp = a;
    a = b;
    b = temp;
}

int x = 1, y = 2;
Swap(ref x, ref y);
// x is 2, y is 1

struct MutablePoint { public int X; public void Flip() => X = -X; }

static int ReadX(in MutablePoint p) => p.X;
// Compiler may copy p defensively because Flip() could mutate

readonly struct SafePoint(int x)
{
    public int X { get; } = x;
}

static int ReadSafe(in SafePoint p) => p.X;
// No defensive copy — readonly struct
